47	      .prepare(
48	        `INSERT INTO coupons (code, type, value, min_amount_cents, max_discount_cents,
49	                              valid_from, valid_until, status, usage_limit)
50	         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
