import { describe, expect, it } from "vitest";
import { createApp } from "../src/app.ts";

const clock = () => new Date("2026-10-01T08:00:00Z");

const makeCoupon = (app: ReturnType<typeof createApp>, body: Record<string, unknown>, status = 201) => {
  const res = app.request("POST", "/coupons", {
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    ...body,
  });
  expect(res.status).toBe(status);
};

describe("apply-coupon", () => {
  it("applies a FIXED coupon", () => {
    const app = createApp({ clock });
    app.request("POST", "/orders", { customer: "a", amountCents: 12000 });
    makeCoupon(app, { code: "FIX20", type: "FIXED", value: 2000 });
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "FIX20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 2000, finalAmountCents: 10000, couponCode: "FIX20", amountCents: 12000 });
  });

  it("applies a PERCENT coupon", () => {
    const app = createApp({ clock });
    app.request("POST", "/orders", { customer: "a", amountCents: 12000 });
    makeCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 2400, finalAmountCents: 9600 });
  });

  it("rejects unknown, disabled, expired and below-minimum coupons with 400", () => {
    const app = createApp({ clock });
    app.request("POST", "/orders", { customer: "a", amountCents: 12000 });
    makeCoupon(app, { code: "OFF", type: "FIXED", value: 100, status: "DISABLED" });
    makeCoupon(app, { code: "OLD", type: "FIXED", value: 100, validUntil: "2025-01-01T00:00:00Z" });
    makeCoupon(app, { code: "BIG", type: "FIXED", value: 100, minAmountCents: 50000 });

    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "NOPE" }).status).toBe(400);
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "OFF" }).status).toBe(400);
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "OLD" }).status).toBe(400);
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "BIG" }).status).toBe(400);
    expect(app.request("POST", "/orders/1/apply-coupon", {}).status).toBe(400);
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "NOPE" }).body).toEqual({
      error: { code: "COUPON_NOT_FOUND", message: expect.any(String) },
    });
  });

  it("honours the max discount cap and never goes below zero", () => {
    const app = createApp({ clock });
    app.request("POST", "/orders", { customer: "a", amountCents: 1000 });
    makeCoupon(app, { code: "CAP", type: "PERCENT", value: 50, maxDiscountCents: 300 });
    makeCoupon(app, { code: "HUGE", type: "FIXED", value: 99999 });
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "CAP" }).body).toMatchObject({ discountCents: 300, finalAmountCents: 700 });
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "HUGE" }).body).toMatchObject({ discountCents: 1000, finalAmountCents: 0 });
  });

  it("tracks usage limit and usedCount", () => {
    const app = createApp({ clock });
    app.request("POST", "/orders", { customer: "a", amountCents: 12000 });
    app.request("POST", "/orders", { customer: "b", amountCents: 12000 });
    makeCoupon(app, { code: "ONCE", type: "FIXED", value: 100, usageLimit: 1 });
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "ONCE" }).status).toBe(200);
    expect(app.request("GET", "/coupons/ONCE").body).toMatchObject({ usedCount: 1 });
    expect(app.request("POST", "/orders/2/apply-coupon", { couponCode: "ONCE" }).status).toBe(400);
  });

  it("returns 404 for an unknown order", () => {
    const app = createApp({ clock });
    makeCoupon(app, { code: "FIX20", type: "FIXED", value: 2000 });
    expect(app.request("POST", "/orders/99/apply-coupon", { couponCode: "FIX20" }).status).toBe(404);
  });
});

